const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1280,height:900}});
  const errors = [], warnings = [], failed = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if(m.type()==='error') errors.push(m.text()); if(m.type()==='warning') warnings.push(m.text()); });
  page.on('requestfailed', r => failed.push(`${r.url()} ${r.failure()?.errorText}`));
  const response = await page.goto('http://127.0.0.1:3000/', {waitUntil:'networkidle'});
  await page.waitForFunction(() => { const c=document.querySelector('#game'); return c && c.width && c.height; });
  const initial = await page.evaluate(() => ({title:document.title, canvas:[game.width,game.height], painted:game.getContext('2d').getImageData(0,0,game.width,game.height).data.reduce((n,v,i)=>n+(i%4===3&&v>0?1:0),0), skills:[...document.querySelectorAll('.spell-name')].map(e=>e.textContent), hero:document.querySelector('#heroClass').textContent}));
  await page.locator('#classSelect').selectOption('mage');
  const mageSkills = await page.locator('.spell-name').allTextContents();
  await page.locator('.spell-slot').nth(1).click();
  const skillSelected = await page.locator('.spell-slot').nth(1).getAttribute('aria-pressed');
  await page.locator('#scoreboardToggle').click();
  const scoreboardOpen = await page.locator('#sidePanel').isVisible();
  await page.locator('#scoreboardToggle').click();
  await page.locator('#helpBtn').click();
  const helpOpen = await page.locator('#helpModal').isVisible();
  await page.locator('#closeHelp').click();
  await page.locator('#menuBtn').click();
  const paused = await page.locator('#menuBtn').textContent();
  await page.keyboard.press('Escape');
  await page.locator('#restartBtn').click();
  const final = await page.evaluate(() => ({hero:document.querySelector('#heroClass').textContent, hp:document.querySelector('#healthValue').textContent}));
  console.log(JSON.stringify({http:response.status(),initial,mageSkills,skillSelected,scoreboardOpen,helpOpen,paused,final,errors,warnings,failed},null,2));
  await browser.close();
  if(response.status()!==200 || !initial.painted || errors.length || failed.length) process.exitCode=1;
})().catch(e=>{console.error(e);process.exit(1)});
